(()=>{const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;function observe(){const items=document.querySelectorAll('.reveal:not(.is-visible), .panel:not(.is-visible), .card:not(.is-visible), .recipe:not(.is-visible), .field:not(.is-visible), h1:not(.is-visible), h2:not(.is-visible), h3:not(.is-visible), .muted:not(.is-visible), .note:not(.is-visible)');if(reduce){items.forEach(el=>el.classList.add('is-visible'));return}const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -50px'});items.forEach((el,i)=>{el.style.setProperty('--reveal-delay',`${Math.min(i%6,5)*70}ms`);io.observe(el)})}function init(){document.documentElement.classList.add('effects-ready');const progress=document.createElement('div');progress.className='scroll-progress';document.body.prepend(progress);const update=()=>{const max=document.documentElement.scrollHeight-window.innerHeight;progress.style.transform=`scaleX(${max>0?window.scrollY/max:0})`};window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();observe();window.BioEffects={observe}}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init()})();